export type GameMode = 'Campaign' | 'Survival' | 'Rescue' | 'Sabotage';
export type GameConfig = { mode: GameMode; level: number; army: number; lives?: number; magic?: number; soldierSkin?: 'Recon'|'Heavy'|'Shadow'; aimAssist?:boolean; aimAssistStrength?:number; autoShoot?:boolean; autoShootRange?:'Short'|'Medium'|'Long'; cameraShake?:boolean; timeOfDay?: 'Night'|'Day'; location?: string; weaponLevel?: number; equippedWeaponId?:string; ownedWeaponIds?:string[]; upgradeLevels?:Record<string,number>; onAutoShootChange?: (enabled:boolean) => void; onUseLife?: () => void; onUseMagic?: () => void; onPause?: () => void; onState: (s: GameState) => void; onExit: () => void };
function tintSoldier(container: Phaser.GameObjects.Container, tint: number) {
  for (const child of container.list) {
    const tintable = child as Phaser.GameObjects.GameObject & { setTint?: (color: number) => unknown };
    if (typeof tintable.setTint === 'function') tintable.setTint(tint);
    else if (child instanceof Phaser.GameObjects.Container) tintSoldier(child, tint);
  }
}
function clearSoldierTint(container: Phaser.GameObjects.Container) {
  for (const child of container.list) {
    const tintable = child as Phaser.GameObjects.GameObject & { clearTint?: () => unknown };
    if (typeof tintable.clearTint === 'function') tintable.clearTint();
    else if (child instanceof Phaser.GameObjects.Container) clearSoldierTint(child);
  }
}

