export function launchGame(parent:HTMLElement,cfg:GameConfig){
  const game=new Phaser.Game({type:Phaser.AUTO,parent,width:parent.clientWidth||960,height:parent.clientHeight||600,backgroundColor:'#07100d',scale:{mode:Phaser.Scale.RESIZE,autoCenter:Phaser.Scale.CENTER_BOTH},physics:{default:'arcade',arcade:{debug:false}},render:{antialias:true,pixelArt:false},scene:[JungleScene],input:{activePointers:3}});
  game.scene.start('jungle',cfg);return game;
}
